/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class MetricsUnitTest {

  @Test
  @DisplayName("Percentiles from the fixed buckets stay close to the real values")
  void percentiles() {
    Histogram histogram = new Histogram();
    for (int i = 1; i <= 1000; i++) {
      histogram.add(i % 100 == 0 ? 800 : 20 + (i % 30));
    }
    Assertions.assertEquals(1000, histogram.total());
    double p50 = histogram.percentile(0.5);
    Assertions.assertTrue(p50 >= 25 && p50 <= 50, "p50 " + p50);
    double p99 = histogram.percentile(0.995);
    Assertions.assertTrue(p99 >= 500 && p99 <= 1000, "p99 " + p99);
    Assertions.assertNull(new Histogram().percentile(0.95));
  }

  @Test
  @DisplayName("Closed minutes are drained once, add up in their hour, and the hour closes after it")
  void drain() {
    MetricDeriver deriver = new MetricDeriver(10);
    long t0 = 1_000 * MetricDeriver.HOUR;
    deriver.record("api", "/orders", "GET", t0 + 1_000, 30, false);
    deriver.record("api", "/orders", "GET", t0 + 2_000, 70, true);
    deriver.record("api", "/orders", "GET", t0 + MetricDeriver.MINUTE, 10, false);
    deriver.record("api", "/observe/api/logs", "GET", t0, 5, false);
    Assertions.assertTrue(deriver.drain(t0 + MetricDeriver.MINUTE + 1).minutes().isEmpty());
    MetricDeriver.Drained first = deriver.drain(t0 + 2 * MetricDeriver.MINUTE + 1);
    Assertions.assertEquals(1, first.minutes().size());
    MetricPoint point = first.minutes().get(0);
    Assertions.assertEquals(2, point.count());
    Assertions.assertEquals(1, point.errors());
    Assertions.assertEquals(100.0, point.sumMs(), 0.001);
    Assertions.assertTrue(first.hours().isEmpty());
    MetricDeriver.Drained later = deriver.drain(t0 + MetricDeriver.HOUR + 2 * MetricDeriver.MINUTE);
    Assertions.assertEquals(1, later.minutes().size());
    Assertions.assertEquals(1, later.hours().size());
    Assertions.assertEquals(3, later.hours().get(0).count());
  }

  @Test
  @DisplayName("Above max-series the new routes of a source go to __overflow__")
  void overflow() {
    MetricDeriver deriver = new MetricDeriver(2);
    long t0 = 1_000 * MetricDeriver.HOUR;
    for (int i = 0; i < 5; i++) {
      deriver.record("api", "/r" + i, "GET", t0, 1, false);
    }
    List<MetricPoint> open = deriver.open();
    Assertions.assertEquals(3, open.size());
    Assertions.assertEquals(3, open.stream().filter(p -> MetricDeriver.OVERFLOW.equals(p.route()))
        .mapToLong(MetricPoint::count).sum());
  }

  @Test
  @DisplayName("Series per step and totals per route: rate, error rate and percentiles")
  void seriesAndRoutes() {
    long t0 = 1_000 * MetricDeriver.HOUR;
    Histogram histogram = new Histogram();
    histogram.add(40);
    histogram.add(60);
    List<MetricPoint> points = List.of(
        new MetricPoint(t0, MetricDeriver.MINUTE, "api", "/a", "GET", 2, 1, 100,
            histogram.counts()),
        new MetricPoint(t0 + MetricDeriver.MINUTE, MetricDeriver.MINUTE, "api", "/a", "GET", 2, 0,
            100, histogram.counts()),
        new MetricPoint(t0, MetricDeriver.MINUTE, "api", "/b", "POST", 6, 0, 60,
            new Histogram().counts()));
    List<Map<String, Object>> series = ObserveMetrics.series(points, t0, 5 * MetricDeriver.MINUTE);
    Assertions.assertEquals(1, series.size());
    Assertions.assertEquals(10L, series.get(0).get("requests"));
    Assertions.assertEquals(2.0, series.get(0).get("rpm"));
    Assertions.assertEquals(10.0, series.get(0).get("errorRate"));
    List<Map<String, Object>> routes = ObserveMetrics.routes(points, 2);
    Assertions.assertEquals("/b", routes.get(0).get("route"));
    Assertions.assertEquals(25.0, routes.get(1).get("errorRate"));
  }
}
